/*
 * A087183  Partition numbers of the form 3*k.
 * https://oeis.org/A087183
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth partition number that is divisible by 3. The
 *            sequence is generated by computing partition numbers p(m) with
 *            the pentagonal‑number recurrence and collecting those for which
 *            p(m) ≡ 0 (mod 3). The terms are cached so that calls to a() are
 *            O(m) in the largest m computed so far and work...
 * Range:     u8 n <= 6, u16 n <= 20, u32 n <= 43, u64 n <= 142, u128 n <= 463,
 *            big any n
 * Helpers:   grow_if_needed
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Standard headers required by the rules. */
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include "../utils/grow_if_needed.h"

/* Forward declarations of the public and static functions. */
seq_t a(idx_t n);
static void compute_partition(idx_t m);

/*---------------------------------------------------------------*/
/*  Dynamic array helpers                                        */

/*---------------------------------------------------------------*/
/*  Global state for the cached partitions and the sequence a() */
/*---------------------------------------------------------------*/
static seq_t      *part_cache  = NULL;   /* p(0) ... p(max_m)          */
static size_t      part_cap    = 0;
static idx_t       part_max    = 0;       /* highest m with a value      */

static uint8_t    *mod3_cache  = NULL;   /* p(m) mod 3, index 0..max_m   */
static size_t      mod3_cap    = 0;

static seq_t      *a_cache     = NULL;   /* collected p(m) ≡ 0 (mod 3)  */
static size_t      a_cap       = 0;
static size_t      a_len       = 0;

/*---------------------------------------------------------------*/
/*  Compute p(m)  (pentagonal‑number recurrence).                */
/*---------------------------------------------------------------*/
static void compute_partition(idx_t m)
{
    if (m <= part_max) return;           /* already computed */

    /* Ensure all buffers are large enough for index m. */
    part_cache  = (seq_t*)  grow_if_needed(part_cache,  &part_cap,  (size_t)m + 1, sizeof(seq_t));
    mod3_cache  = (uint8_t*)grow_if_needed(mod3_cache,  &mod3_cap,  (size_t)m + 1, sizeof(uint8_t));

    seq_t  sum = (seq_t)0;   /* use seq_t for arithmetic; 
                               subtraction is safe for the
                               recurrence (intermediate
                               partial sums never become
                               negative).                      */
    int    mod = 0;           /* modulo 3 accumulator */

    for (int k = 1; ; ++k)
    {
        idx_t g1 = k * (3 * k - 1) / 2;
        if (g1 > m) break;
        int sign = (k & 1) ? 1 : -1;

        if (sign > 0) sum += part_cache[m - g1];
        else          sum -= part_cache[m - g1];

        mod += sign * mod3_cache[m - g1];
        mod %= 3; if (mod < 0) mod += 3;

        idx_t g2 = k * (3 * k + 1) / 2;
        if (g2 > m) continue;

        if (sign > 0) sum += part_cache[m - g2];
        else          sum -= part_cache[m - g2];

        mod += sign * mod3_cache[m - g2];
        mod %= 3; if (mod < 0) mod += 3;
    }

    part_cache[m] = sum;
    mod3_cache[m] = (uint8_t)(mod % 3);

    if (mod == 0) {
        /* Append to the sequence a() cache. */
        a_cache = (seq_t*)grow_if_needed(a_cache, &a_cap, a_len + 1, sizeof(seq_t));
        a_cache[a_len++] = sum;
    }

    part_max = m;
}

/*---------------------------------------------------------------*/
/*  Public entry point for the OEIS sequence A087183.            */
/*---------------------------------------------------------------*/
seq_t a(idx_t n)
{
    if (n == 0) return 0;               /* undefined, but harmless */

    /* Initialisation on first call.  p(0) = 1, mod 3 = 1. */
    if (!part_cache) {
        part_cache  = (seq_t*)  malloc(sizeof(seq_t));
        part_cap    = 1;
        part_cache[0] = (seq_t)1;
        part_max     = 0;

        mod3_cache  = (uint8_t*)malloc(sizeof(uint8_t));
        mod3_cap    = 1;
        mod3_cache[0] = 1 % 3;

        a_cache = (seq_t*)malloc(sizeof(seq_t));
        a_cap   = 0;
        a_len   = 0;
    }

    /* Keep generating partition numbers until we have n terms
       divisible by 3. */
    while (a_len < (size_t)n) {
        idx_t next_m = part_max + 1;
        compute_partition(next_m);
    }

    return a_cache[n - 1];
}
